import{_ as o,o as s,c as a,a0 as t}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"Proactive Permissions for Safe Commands","description":"Guidelines for agents to request persistent permissions for common, safe shell commands to reduce user interruption.","frontmatter":{"isInternal":true,"type":"Architecture Decision Record","title":"Proactive Permissions for Safe Commands","description":"Guidelines for agents to request persistent permissions for common, safe shell commands to reduce user interruption.","tags":["permissions","agent-ux","workflow"]},"headers":[],"relativePath":"adr/2026-07-05-proactive-permissions-for-safe-commands.md","filePath":"adr/2026-07-05-proactive-permissions-for-safe-commands.md"}'),r={name:"adr/2026-07-05-proactive-permissions-for-safe-commands.md"};function n(i,e,c,d,m,l){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="proactive-permissions-for-safe-commands" tabindex="-1">Proactive Permissions for Safe Commands <a class="header-anchor" href="#proactive-permissions-for-safe-commands" aria-label="Permalink to &quot;Proactive Permissions for Safe Commands&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>During standard development workflows, AI agents frequently execute routine shell commands (e.g., source control operations, CI/CD checks). By default, the execution sandbox requires explicit user approval for every command, which disrupts the flow of autonomous work and increases the user&#39;s interaction burden.</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Frequent prompts for undeniably safe, routine commands (like <code>git status</code>, <code>git commit</code>, <code>gh run list</code>) slow down the agent&#39;s progress and frustrate the user.</p><h2 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to &quot;Solution&quot;">​</a></h2><p>When beginning a complex task that heavily involves source control or CI/CD interactions, agents <strong>SHOULD</strong> proactively request persistent permissions for safe command prefixes using their available permission tools.</p><h3 id="approved-safe-commands" tabindex="-1">Approved Safe Commands <a class="header-anchor" href="#approved-safe-commands" aria-label="Permalink to &quot;Approved Safe Commands&quot;">​</a></h3><p>Agents are authorized to request blanket exceptions for the following command prefixes:</p><ul><li><code>git</code> (enables seamless commits, branch creation, merging, and status checks)</li><li><code>gh</code> (enables seamless interaction with GitHub Actions and PRs)</li></ul><h3 id="excluded-commands-do-not-request" tabindex="-1">Excluded Commands (Do NOT request) <a class="header-anchor" href="#excluded-commands-do-not-request" aria-label="Permalink to &quot;Excluded Commands (Do NOT request)&quot;">​</a></h3><p>Agents must <strong>NEVER</strong> request persistent exceptions for commands that make unverified network requests, run arbitrary code, or modify the system outside the workspace context. Examples include:</p><ul><li><code>npm</code> or <code>npx</code> (as package scripts can execute arbitrary node code)</li><li><code>curl</code> or <code>wget</code></li><li><code>pip</code></li></ul><p>By keeping the permission scope narrow and strictly limited to safe operations, we balance security with autonomous efficiency.</p>',14)])])}const f=o(r,[["render",n]]);export{p as __pageData,f as default};
